#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 999 || n % 2 == 0) return 1;
    std::vector<int> values;
    for (int i = 0; i < n; i++) {
        int value = 0;
        if (!(std::cin >> value)) return 1;
        if (value < -10000 || value > 10000) return 1;
        values.push_back(value);
    }
    std::sort(values.begin(), values.end());
    std::cout << values[values.size() / 2] << std::endl;
    return 0;
}
